/**
 * generated by stackra gen from src/config/seo.config.ts (og), src/config/theming.config.ts (logo)
 * and assets/public/logo.svg — do not edit
 * Purpose: `/og/<kind>/<id>`: the Open Graph image of a site, a page or a product, rendered on the
 *          Worker from the site's brand tokens and the logo mark, cached at the edge for
 *          `og.cacheSeconds`.
 * Boundary: reads through the same route context and public clients as every loader; an unknown
 *           kind or id is a 404.
 * Runtime: worker
 */
import { routeContext } from "@stackra/navigation/router";
import { OgKind } from "@stackra/seo";
import { renderOgImage } from "@stackra/seo/og";
import type { Route } from "./+types/og-image";
import { Commerce, Experience } from "#stackra/clients";
import { SeoConfig } from "#src/config/seo.config";
import { resolveSite } from "#src/providers/site/resolve-site";
import logo from "#assets/public/logo.svg?raw";

export async function loader(args: Route.LoaderArgs) {
  const ctx = routeContext(args);
  const og = ctx.config(SeoConfig).og;
  const kind = OgKind.tryFrom(args.params.kind);
  if (!kind || !og.kinds.includes(kind)) return new Response(null, { status: 404 });
  const site = await resolveSite(ctx);

  let title = site.name;
  let image: string | undefined;
  if (kind === OgKind.Product) {
    const product = await ctx
      .query(Commerce.queries.GetProductBySlug, { slug: args.params.id })
      .catch(() => null);
    if (!product) return new Response(null, { status: 404 });
    title = product.title;
    image = product.images[0]?.url;
  } else if (kind === OgKind.Page) {
    const page = await ctx.query(Experience.queries.GetDocument, { path: `/${args.params.id}` });
    title = page?.seo.title ?? site.name;
  }

  const png = await renderOgImage({
    template: kind,
    width: og.width,
    height: og.height,
    title,
    siteName: site.name,
    dir: site.dir,
    brand: site.brand,
    logo,
    image,
  });
  return new Response(png, {
    headers: {
      "Content-Type": "image/png",
      "Cache-Control": `public, max-age=0, s-maxage=${og.cacheSeconds}`,
    },
  });
}
